INSERT INTO email_templates (business_profile_id, name, category, subject, preheader, body, body_html, body_text, followup_stage, active, created_at, updated_at) VALUES
(1, 'Initial Outreach - Skincare/Cosmetic Formulators', 'Skincare / cosmetic formulators', 'Peptide sourcing support for {{company_name}}', 'MOQ flexibility, documentation support, and batch transparency for skincare formulation teams.', 'Hello {{contact_name}},\n\nI am reaching out from {{brand_name}} regarding peptide sourcing support for qualified B2B skincare and cosmetic formulation teams.\n\n{{brand_name}} helps buyers structure sourcing conversations around MOQ flexibility, documentation support, batch transparency, and clear commercial follow-up.\n\nWhat we can support:\n- MOQ planning for early-stage or scaling programs\n- Documentation-first discussions for internal review\n- Batch transparency and practical sourcing coordination\n\nIf this is relevant for {{company_name}}, we would be glad to discuss current requirements.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I am reaching out from {{brand_name}} regarding peptide sourcing support for qualified B2B skincare and cosmetic formulation teams.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">{{brand_name}} helps buyers structure sourcing conversations around MOQ flexibility, documentation support, batch transparency, and clear commercial follow-up.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">How {{brand_name}} can support</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">MOQ planning for early-stage or scaling programs</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Documentation-first discussions for internal technical review</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">Batch transparency and practical sourcing coordination</td></tr></table></td></tr></table><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If this is relevant for {{company_name}}, we would be glad to discuss current requirements and next steps.</p><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20Sourcing%20Needs\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Discuss Sourcing Needs</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">Or simply reply to this email and share the product, quantity range, or documentation priorities you are reviewing.</div>', 'Hello {{contact_name}},\n\nI am reaching out from {{brand_name}} regarding peptide sourcing support for qualified B2B skincare and cosmetic formulation teams.\n\n{{brand_name}} helps buyers structure sourcing conversations around MOQ flexibility, documentation support, batch transparency, and clear commercial follow-up.\n\nWhat we can support:\n- MOQ planning for early-stage or scaling programs\n- Documentation-first discussions for internal review\n- Batch transparency and practical sourcing coordination\n\nIf this is relevant for {{company_name}}, we would be glad to discuss current requirements.\n\nReply to: {{reply_to_email}}\n\n{{default_signature}}', 0, 1, NOW(), NOW()),
(1, 'Initial Outreach - Ingredient Distributors', 'Ingredient distributors', 'Documented sourcing coordination for {{company_name}}', 'A clear sourcing introduction for ingredient distribution teams.', 'Hello {{contact_name}},\n\n{{brand_name}} supports peptide sourcing with documentation support, batch transparency, MOQ flexibility, and commercially clear coordination for qualified B2B buyers.\n\nFor distribution teams, we focus on practical supply conversations, documentation readiness, and professional follow-up.\n\nWhat we can support:\n- Structured RFQ discussions\n- Documentation alignment for internal review\n- Supply coordination for qualified opportunities\n\nIf useful, we would be glad to learn what {{company_name}} is currently evaluating.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">{{brand_name}} supports peptide sourcing with documentation support, batch transparency, MOQ flexibility, and commercially clear coordination for qualified B2B buyers.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">For distribution teams, we focus on practical supply conversations, documentation readiness, and professional follow-up.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">Distribution support focus</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Structured RFQ discussions with a business-first tone</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Documentation alignment for internal buyer review</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">Supply coordination for qualified opportunities</td></tr></table></td></tr></table><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If useful, we would be glad to learn what {{company_name}} is currently evaluating.</p><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20RFQ%20Discussion\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Review Requirements</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">You can also reply directly with the categories or sourcing priorities your team is reviewing.</div>', 'Hello {{contact_name}},\n\n{{brand_name}} supports peptide sourcing with documentation support, batch transparency, MOQ flexibility, and commercially clear coordination for qualified B2B buyers.\n\nFor distribution teams, we focus on practical supply conversations, documentation readiness, and professional follow-up.\n\nWhat we can support:\n- Structured RFQ discussions\n- Documentation alignment for internal review\n- Supply coordination for qualified opportunities\n\nIf useful, we would be glad to learn what {{company_name}} is currently evaluating.\n\nReply to: {{reply_to_email}}\n\n{{default_signature}}', 0, 1, NOW(), NOW()),
(1, 'Initial Outreach - Contract Manufacturers', 'Contract manufacturers', 'Supply coordination support for {{company_name}}', 'MOQ planning, documentation support, and sourcing coordination for manufacturing teams.', 'Hello {{contact_name}},\n\nI am contacting you from {{brand_name}} regarding peptide sourcing support for qualified B2B manufacturing teams.\n\n{{brand_name}} helps structure conversations around MOQ planning, documentation support, batch transparency, and coordinated next steps before commercial decisions move forward.\n\nWhat we can support:\n- Early scoping conversations for sourcing fit\n- Documentation support for internal stakeholder review\n- Coordinated follow-up around quantities, timing, and supply expectations\n\nIf useful, we would be glad to discuss what {{company_name}} is currently working through.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I am contacting you from {{brand_name}} regarding peptide sourcing support for qualified B2B manufacturing teams.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">{{brand_name}} helps structure conversations around MOQ planning, documentation support, batch transparency, and coordinated next steps before commercial decisions move forward.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">Manufacturing support focus</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Early scoping conversations for sourcing fit</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Documentation support for internal stakeholder review</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">Coordinated follow-up on quantities, timing, and supply expectations</td></tr></table></td></tr></table><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If useful, we would be glad to discuss what {{company_name}} is currently working through.</p><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20Manufacturing%20Discussion\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Discuss Sourcing Needs</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">Reply with your quantity range, timing window, or documentation priorities and we can take it from there.</div>', 'Hello {{contact_name}},\n\nI am contacting you from {{brand_name}} regarding peptide sourcing support for qualified B2B manufacturing teams.\n\n{{brand_name}} helps structure conversations around MOQ planning, documentation support, batch transparency, and coordinated next steps before commercial decisions move forward.\n\nWhat we can support:\n- Early scoping conversations for sourcing fit\n- Documentation support for internal stakeholder review\n- Coordinated follow-up around quantities, timing, and supply expectations\n\nIf useful, we would be glad to discuss what {{company_name}} is currently working through.\n\nReply to: {{reply_to_email}}\n\n{{default_signature}}', 0, 1, NOW(), NOW()),
(1, 'Initial Outreach - Research Supply Buyers', 'Research supply buyers', 'Professional sourcing support for {{company_name}}', 'Documentation-first sourcing support for qualified research supply buyers.', 'Hello {{contact_name}},\n\n{{brand_name}} supports qualified B2B research supply buyers with professional sourcing coordination, MOQ flexibility, documentation support, and batch transparency.\n\nOur focus is straightforward business communication around supply requirements, documentation expectations, and practical RFQ follow-up.\n\nWhat we can support:\n- Documentation-first sourcing discussions\n- Clear supply communication for internal teams\n- Coordinated next steps for qualified RFQs\n\nIf this is relevant for {{company_name}}, we would be glad to continue the conversation.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">{{brand_name}} supports qualified B2B research supply buyers with professional sourcing coordination, MOQ flexibility, documentation support, and batch transparency.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">Our focus is straightforward business communication around supply requirements, documentation expectations, and practical RFQ follow-up.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">Research buyer support</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Documentation-first sourcing discussions</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Clear supply communication for internal teams</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">Coordinated next steps for qualified RFQs</td></tr></table></td></tr></table><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If this is relevant for {{company_name}}, we would be glad to continue the conversation.</p><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20Research%20Supply%20Inquiry\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Request a Quote</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">If you prefer, reply directly with the product and quantity range you are reviewing.</div>', 'Hello {{contact_name}},\n\n{{brand_name}} supports qualified B2B research supply buyers with professional sourcing coordination, MOQ flexibility, documentation support, and batch transparency.\n\nOur focus is straightforward business communication around supply requirements, documentation expectations, and practical RFQ follow-up.\n\nWhat we can support:\n- Documentation-first sourcing discussions\n- Clear supply communication for internal teams\n- Coordinated next steps for qualified RFQs\n\nIf this is relevant for {{company_name}}, we would be glad to continue the conversation.\n\nReply to: {{reply_to_email}}\n\n{{default_signature}}', 0, 1, NOW(), NOW()),
(1, 'Follow-Up 1', 'Other', 'Following up from {{brand_name}}', 'A quick follow-up in case sourcing requirements are being reviewed internally.', 'Hello {{contact_name}},\n\nI wanted to follow up on my earlier note from {{brand_name}}.\n\nIf {{company_name}} is still reviewing peptide sourcing needs, we would be glad to continue the conversation around MOQ flexibility, documentation support, and batch transparency.\n\nIf useful, reply with the category or sourcing requirement your team is reviewing.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I wanted to follow up on my earlier note from {{brand_name}}.</p><p style=\"margin:0 0 20px;font-size:16px;line-height:26px;color:#243548;\">If {{company_name}} is still reviewing peptide sourcing needs, we would be glad to continue the conversation around MOQ flexibility, documentation support, and batch transparency.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 22px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:18px 20px;\"><div style=\"font-size:15px;line-height:24px;color:#243548;\">If useful, reply with the category, quantity range, or documentation requirement your team is reviewing.</div></td></tr></table><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20Follow-up\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Reply to This Email</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">We can keep the conversation focused and practical if timing is right.</div>', 'Hello {{contact_name}},\n\nI wanted to follow up on my earlier note from {{brand_name}}.\n\nIf {{company_name}} is still reviewing peptide sourcing needs, we would be glad to continue the conversation around MOQ flexibility, documentation support, and batch transparency.\n\nIf useful, reply with the category or sourcing requirement your team is reviewing.\n\n{{default_signature}}', 1, 1, NOW(), NOW()),
(1, 'Follow-Up 2', 'Other', 'Closing the loop from {{brand_name}}', 'A final respectful follow-up from {{brand_name}}.', 'Hello {{contact_name}},\n\nI am closing the loop on my previous outreach from {{brand_name}}.\n\nIf sourcing support, documentation alignment, MOQ planning, or batch transparency becomes relevant for {{company_name}}, we would be glad to help when timing is better.\n\nThank you for your time.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I am closing the loop on my previous outreach from {{brand_name}}.</p><p style=\"margin:0 0 20px;font-size:16px;line-height:26px;color:#243548;\">If sourcing support, documentation alignment, MOQ planning, or batch transparency becomes relevant for {{company_name}}, we would be glad to help when timing is better.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 22px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:18px 20px;\"><div style=\"font-size:15px;line-height:24px;color:#243548;\">Thank you for your time. If you would like us to circle back later, a simple reply is enough.</div></td></tr></table><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20Future%20Follow-up\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Keep in Touch</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">No pressure. We prefer concise, useful follow-up over repeated noise.</div>', 'Hello {{contact_name}},\n\nI am closing the loop on my previous outreach from {{brand_name}}.\n\nIf sourcing support, documentation alignment, MOQ planning, or batch transparency becomes relevant for {{company_name}}, we would be glad to help when timing is better.\n\nThank you for your time.\n\n{{default_signature}}', 2, 1, NOW(), NOW()),
(1, 'RFQ Confirmation', 'Other', 'We received your {{brand_name}} RFQ', 'Your request is in. {{brand_name}} will review the details and follow up with next steps.', 'Hello {{contact_name}},\n\nThank you for contacting {{brand_name}}. We received your RFQ and will review the request for sourcing fit, documentation expectations, MOQ support, and next-step coordination.\n\nWhat happens next:\n- Your request is reviewed by the team\n- We assess product interest, quantity, and documentation needs\n- We follow up using the contact details you provided\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 20px;font-size:16px;line-height:26px;color:#243548;\">Thank you for contacting {{brand_name}}. We received your RFQ and will review the request for sourcing fit, documentation expectations, MOQ support, and next-step coordination.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">What happens next</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Your request is reviewed by the team</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">We assess product interest, quantity, and documentation needs</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">We follow up using the contact details you provided</td></tr></table></td></tr></table><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20RFQ%20Follow-up\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Reply with Additional Details</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">If there is anything else we should review, feel free to reply directly to this email.</div>', 'Hello {{contact_name}},\n\nThank you for contacting {{brand_name}}. We received your RFQ and will review the request for sourcing fit, documentation expectations, MOQ support, and next-step coordination.\n\nWhat happens next:\n- Your request is reviewed by the team\n- We assess product interest, quantity, and documentation needs\n- We follow up using the contact details you provided\n\n{{default_signature}}', 9, 1, NOW(), NOW()),
(1, 'Quote Follow-Up', 'Other', 'Following up on your {{brand_name}} quote', 'A practical follow-up after your quote or sourcing discussion.', 'Hello {{contact_name}},\n\nI wanted to follow up on the quote or sourcing discussion with {{brand_name}}.\n\nIf your team is reviewing quantities, timing, documentation, or commercial fit, we would be glad to help move the conversation forward.\n\nIf useful, reply with any open questions and we can respond directly.\n\n{{default_signature}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I wanted to follow up on the quote or sourcing discussion with {{brand_name}}.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If your team is reviewing quantities, timing, documentation, or commercial fit, we would be glad to help move the conversation forward.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:18px 20px;\"><div style=\"font-size:15px;line-height:24px;color:#243548;\">If useful, reply with any open questions and we can respond directly with the next best step.</div></td></tr></table><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject={{brand_name}}%20Quote%20Follow-up\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Continue the Discussion</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">We can keep the follow-up focused on the details your team needs to review internally.</div>', 'Hello {{contact_name}},\n\nI wanted to follow up on the quote or sourcing discussion with {{brand_name}}.\n\nIf your team is reviewing quantities, timing, documentation, or commercial fit, we would be glad to help move the conversation forward.\n\nIf useful, reply with any open questions and we can respond directly.\n\n{{default_signature}}', 3, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE
category = VALUES(category),
subject = VALUES(subject),
preheader = VALUES(preheader),
body = VALUES(body),
body_html = VALUES(body_html),
